import{_ as d,a0 as s,w as p,s as l,ao as u,I as r,x as t,a1 as i,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"Intel 展示了可在大屏幕顯示 Linux 系統的低端 Android 手機 | LCTT x X-CMD","titleTemplate":false,"description":"Intel 展示了可在大屏幕顯示 Linux 系統的低端 Android 手機 | LCTT (201605) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Intel 展示了可在大屏幕顯示 Linux 系統的低端 Android 手機 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Intel 展示了可在大屏幕顯示 Linux 系統的低端 Android 手機 | LCTT (201605) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201605/20160223 Intel shows budget Android phone powering big-screen Linux","title":"Intel 展示了可在大屏幕顯示 Linux 系統的低端 Android 手機","tag":"201605","desc":""},"relativePath":"201605/20160223 Intel shows budget Android phone powering big-screen Linux.md","filePath":"[post].md"}'),a={name:"201605/20160223 Intel shows budget Android phone powering big-screen Linux.md"};function m(x,n,g,_,L,w){const e=s("Link");return p(),l("div",null,[n[13]||(n[13]=u('<h1 id="intel-展示了可在大屏幕顯示-linux-系統的低端-android-手機" tabindex="-1">Intel 展示了可在大屏幕顯示 Linux 系統的低端 Android 手機 <a class="header-anchor" href="#intel-展示了可在大屏幕顯示-linux-系統的低端-android-手機" aria-label="Permalink to “Intel 展示了可在大屏幕顯示 Linux 系統的低端 Android 手機”">​</a></h1><p><img src="https://regmedia.co.uk/2016/02/23/intel-bigscreen.jpg?x=648&amp;y=348&amp;crop=1" alt=""></p><p>在世界移動大會 <strong>MWC16</strong> 上 Intel 展示了稱之為“大屏體驗”的一款的 Android 智能手機，它在插入一個外部顯示後運行了一個完整的 Linux 桌面。</p><p>這個概念大體上與微軟在 Windows 10 手機中的 Continuum 相似，但是 Continuum 面向的是高端設備，Intel 的項目面向的是低端智能機和新興市場。</p><p>在巴塞羅那的這場大會上展示的是擁有 Atom x3、2GB RAM 和 16GB 存儲以及支持外部顯示的的 SoFIA（Intel 架構的智能或功能手機）智能機原型。插上鍵盤、鼠標和顯示，它就變成了一台桌面 Linux，並可以選擇在大屏幕的一個窗口中顯示 Android 桌面。</p><p>Intel 的拓荒小組（Path Finding Group）經理 Nir Metzer 告訴我們：“Android 基於 Linux 內核，因此我們運行在一個內核上，我們有一個 Android 棧和一個 Linux 棧，並且我們共享同一個環境，因此文件系統是相同的。電話是全功能的。”</p><p>Metzer 説：“我有一個多窗口環境。只要我插入顯示器後就可以使用電子表格，我可以進行拖放操作，播放音頻。在一個低端平台實現這一切是一個挑戰。”</p><p>現在當連上外部顯示器時設備的屏幕顯示是空白的，但是 Metzer 説下個版本的 Atom X3 會支持雙顯示。</p><p>其使用的 Linux 版本是由 Intel 維護的。Metzer 説：“我們需要將 Linux 和 Android 保持一致。框架是預安裝的，你不能下載任何 app。”</p><p>英特爾在移動世界大會上向手機制造商們推銷這一想法，但卻沒有實際説希望購買該設備的消費者。Metzer 説：“芯片已經準備好了，已經為量產準備好了。明天就可以進入生產。但是這要看商業需求。”</p><hr>',11)),r("p",null,[n[1]||(n[1]=t("via: ",-1)),i(e,{href:"http://www.theregister.co.uk/2016/02/23/move_over_continuum_intel_shows_android_smartphone_powering_bigscreen_linux/"},{default:o(()=>[...n[0]||(n[0]=[t("http://www.theregister.co.uk/2016/02/23/move_over_continuum_intel_shows_android_smartphone_powering_bigscreen_linux/",-1)])]),_:1})]),r("p",null,[n[5]||(n[5]=t("作者：",-1)),i(e,{href:"http://www.theregister.co.uk/Author/2878"},{default:o(()=>[...n[2]||(n[2]=[t("Tim Anderson",-1)])]),_:1}),n[6]||(n[6]=t(" 譯者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:o(()=>[...n[3]||(n[3]=[t("geekpi",-1)])]),_:1}),n[7]||(n[7]=t(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:o(()=>[...n[4]||(n[4]=[t("wxy",-1)])]),_:1})]),r("p",null,[n[10]||(n[10]=t("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...n[8]||(n[8]=[t("LCTT",-1)])]),_:1}),n[11]||(n[11]=t(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:o(()=>[...n[9]||(n[9]=[t("Linux中國",-1)])]),_:1}),n[12]||(n[12]=t(" 榮譽推出",-1))])])}const I=d(a,[["render",m]]);export{f as __pageData,I as default};
